<script>
  const costSlider = document.getElementById('cost');
  const timeSlider = document.getElementById('time');
  const envSlider = document.getElementById('env');

  function updateScores() {
    const c = parseFloat(costSlider.value);
    const t = parseFloat(timeSlider.value);
    const e = parseFloat(envSlider.value);
    const sum = c + t + e;

    // Normalize to 100
    const cW = c / sum;
    const tW = t / sum;
    const eW = e / sum;

    document.getElementById('cost-val').textContent = c + '%';
    document.getElementById('time-val').textContent = t + '%';
    document.getElementById('env-val').textContent = e + '%';
    document.getElementById('sum').textContent = sum + '%';

    // Scoring: lower is better (normalized to train = 1.0)
    const trainScore = cW * 1.0 + tW * 1.0 + eW * 1.0;
    const carScore = cW * 1.26 + tW * 1.18 + eW * 3.33;

    // Scale to 0-100 for display
    const trainDisplay = Math.round(100);
    const carDisplay = Math.round((carScore / trainScore) * 100);

    document.getElementById('train-score').textContent = trainDisplay;
    document.getElementById('car-score').textContent = carDisplay;

    const rec = document.getElementById('recommendation');
    if (carDisplay > 110) {
      rec.textContent = '✅ Zug ist deutlich besser.';
      rec.style.background = 'rgba(0, 200, 100, 0.15)';
    } else if (carDisplay > 100) {
      rec.textContent = '⚖️ Zug ist knapp besser – je nach Flexibilität könnte Auto auch Sinn machen.';
      rec.style.background = 'rgba(255, 150, 0, 0.15)';
    } else {
      rec.textContent = '🚗 Auto wird besser, wenn Zeit/Flexibilität überwiegt.';
      rec.style.background = 'rgba(255, 100, 100, 0.15)';
    }
  }

  costSlider.addEventListener('input', updateScores);
  timeSlider.addEventListener('input', updateScores);
  envSlider.addEventListener('input', updateScores);

  updateScores();
</script>
