```hui
{
  "type": "calc",
  "id": "wien_graz_calc",
  "title": "Wien–Graz: Kosten–Zeit–Umwelt Kalkulator",
  "inputs": [
    {
      "name": "kosten_weight",
      "label": "Kosten Gewicht (%)",
      "kind": "slider",
      "min": 0,
      "max": 100,
      "default": 50
    },
    {
      "name": "zeit_weight",
      "label": "Zeit Gewicht (%)",
      "kind": "slider",
      "min": 0,
      "max": 100,
      "default": 20
    },
    {
      "name": "umwelt_weight",
      "label": "Umwelt Gewicht (%)",
      "kind": "slider",
      "min": 0,
      "max": 100,
      "default": 30
    }
  ],
  "outputs": [
    {
      "label": "Zug-Score (0–100)",
      "expr": "(8 * kosten_weight + 9 * zeit_weight + 9 * umwelt_weight) / (kosten_weight + zeit_weight + umwelt_weight)"
    },
    {
      "label": "Auto-Score (0–100)",
      "expr": "(7 * kosten_weight + 6 * zeit_weight + 3 * umwelt_weight) / (kosten_weight + zeit_weight + umwelt_weight)"
    },
    {
      "label": "Empfehlung",
      "expr": "IF((8 * kosten_weight + 9 * zeit_weight + 9 * umwelt_weight) / (kosten_weight + zeit_weight + umwelt_weight) > (7 * kosten_weight + 6 * zeit_weight + 3 * umwelt_weight) / (kosten_weight + zeit_weight + umwelt_weight), \"→ Zug\", \"→ Auto\")"
    }
  ]
}
```

